package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/combust-labs/macos-power-consumption-exporter/internal/power_usage_exporter"
	"github.com/combust-labs/macos-power-consumption-exporter/internal/power_usage_reader"
	"github.com/combust-labs/macos-power-consumption-exporter/pkg/metrics"
	"github.com/rs/zerolog"
	"github.com/rs/zerolog/log"
)

var (
	// Version is set at build time
	Version = "dev"

	// Commit is set at build time
	Commit = "unknown"

	// Default port file path
	defaultPortFile = "$HOME/.macos-power-consumption-exporter-port-file"
)

func getEnvOrDefault(key, defaultVal string) string {
	if val := os.Getenv(key); val != "" {
		return val
	}
	return defaultVal
}

func main() {
	// Parse flags
	exporterAddr := flag.String("addr", ":8080", "HTTP server address")
	logLevel := flag.String("log-level", "info", "Log level (debug, info, warn, error)")
	authHeaderFile := flag.String("auth-header-file", "", "Path to file containing auth token (enables auth on /metrics)")
	portFile := flag.String("port-file", getEnvOrDefault("EXPORTER_PORT_FILE", defaultPortFile), "Path to file for ephemeral port (use with -addr :0)")
	portRangeStart := flag.Int("port-range-start", 8000, "Start of port range for ephemeral binding")
	portRangeEnd := flag.Int("port-range-end", 9000, "End of port range for ephemeral binding")
	flag.Parse()

	// Set up logging
	configureLogging(*logLevel)

	log.Info().
		Str("version", Version).
		Str("commit", Commit).
		Msg("starting macos-power-consumption-exporter")

	// Get hostname for metrics
	hostname, err := os.Hostname()
	if err != nil {
		log.Fatal().Err(err).Msg("failed to get hostname")
	}

	// Create context with cancellation
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Set up signal handling
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		sig := <-sigCh
		log.Info().Str("signal", sig.String()).Msg("received shutdown signal")
		cancel()
	}()

	// Create and start the exporter
	exporter, err := power_usage_exporter.New(&power_usage_exporter.Config{
		Addr:           *exporterAddr,
		AuthHeaderFile: *authHeaderFile,
		PortFile:       *portFile,
		PortRangeStart: *portRangeStart,
		PortRangeEnd:   *portRangeEnd,
	})
	if err != nil {
		log.Fatal().Err(err).Msg("failed to create exporter")
	}

	if err := exporter.Start(ctx); err != nil {
		log.Fatal().Err(err).Msg("failed to start exporter")
	}

	log.Info().Str("addr", exporter.Addr()).Msg("exporter started")

	// Create and start the reader with automatic restart
	reader, err := power_usage_reader.New()
	if err != nil {
		log.Fatal().Err(err).Msg("failed to create reader")
	}

	// Start reader with restart logic
	runReaderWithRestart(ctx, reader, hostname)

	log.Info().Msg("shutting down")

	// Stop exporter
	if err := exporter.Stop(); err != nil {
		log.Error().Err(err).Msg("error stopping exporter")
	}

	log.Info().Msg("shutdown complete")
}

func runReaderWithRestart(ctx context.Context, reader *power_usage_reader.PowerUsageReader, hostname string) {
	backoff := time.Second
	maxBackoff := 30 * time.Second

	for {
		select {
		case <-ctx.Done():
			reader.Stop()
			return
		default:
		}

		// Start the reader
		if err := reader.Start(ctx); err != nil {
			log.Error().Err(err).Msg("failed to start reader, will retry")
			incrementRestartCounter(hostname)
			backoff = sleepWithContext(ctx, backoff)
			backoff = minDuration(backoff*2, maxBackoff)
			continue
		}

		// Reader started successfully, reset backoff
		backoff = time.Second

		// Wait for reader to stop or context to cancel
		<-ctx.Done()
		reader.Stop()

		// Check if we should restart
		select {
		case <-ctx.Done():
			return
		default:
		}

		log.Info().Msg("reader stopped, restarting")
		incrementRestartCounter(hostname)
	}
}

func incrementRestartCounter(hostname string) {
	metrics.ReaderRestartCount.WithLabelValues(hostname).Inc()
	log.Info().Msg("reader restart counter incremented")
}

func sleepWithContext(ctx context.Context, duration time.Duration) time.Duration {
	select {
	case <-ctx.Done():
		return duration
	case <-time.After(duration):
		return duration
	}
}

func minDuration(a, b time.Duration) time.Duration {
	if a < b {
		return a
	}
	return b
}

func configureLogging(level string) {
	zerolog.TimeFieldFormat = zerolog.TimeFormatUnix

	lvl, err := zerolog.ParseLevel(level)
	if err != nil {
		fmt.Fprintf(os.Stderr, "invalid log level: %s, defaulting to info\n", level)
		lvl = zerolog.InfoLevel
	}

	zerolog.SetGlobalLevel(lvl)

	// Console output with colors
	log.Logger = log.Output(zerolog.ConsoleWriter{
		Out:     os.Stderr,
		NoColor: os.Getenv("NO_COLOR") != "",
	})
}

package power_usage_exporter

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"
	"github.com/rs/zerolog/log"
)

// Config holds the exporter configuration
type Config struct {
	Addr           string
	AuthHeaderFile string
	PortFile       string
	PortRangeStart int
	PortRangeEnd   int
}

// PowerUsageExporter exposes power metrics via HTTP
type PowerUsageExporter struct {
	config    *Config
	server    *http.Server
	listener  net.Listener
	authToken string
	portFile  string
}

// New creates a new PowerUsageExporter
func New(config *Config) (*PowerUsageExporter, error) {
	if config.Addr == "" {
		config.Addr = ":8080"
	}

	exporter := &PowerUsageExporter{
		config: config,
	}

	// Expand tilde in port file path
	if config.PortFile != "" {
		exporter.portFile = expandPortFilePath(config.PortFile)
	}

	// Load auth token if configured
	if config.AuthHeaderFile != "" {
		token, err := os.ReadFile(config.AuthHeaderFile)
		if err != nil {
			return nil, fmt.Errorf("failed to read auth header file: %w", err)
		}
		exporter.authToken = strings.TrimSpace(string(token))
		log.Info().Str("auth-header-file", config.AuthHeaderFile).Msg("auth enabled for /metrics endpoint")
	}

	return exporter, nil
}

// Start starts the HTTP server
func (e *PowerUsageExporter) Start(ctx context.Context) error {
	log.Info().Str("addr", e.config.Addr).Msg("starting power usage exporter")

	// Create listener (handle :0 for ephemeral port)
	var ln net.Listener
	var err error

	if e.config.Addr == ":0" {
		port, err := e.findAvailablePort(e.config.PortRangeStart, e.config.PortRangeEnd)
		if err != nil {
			return fmt.Errorf("failed to find available port: %w", err)
		}
		ln, err = net.Listen("tcp", fmt.Sprintf(":%d", port))
		if err != nil {
			return fmt.Errorf("failed to create listener on ephemeral port: %w", err)
		}
		log.Info().Int("port", port).Msg("bound to ephemeral port")

		// Write port to file
		if e.portFile != "" {
			if err := e.writePortFile(port); err != nil {
				ln.Close()
				return fmt.Errorf("failed to write port file: %w", err)
			}
		}
	} else {
		ln, err = net.Listen("tcp", e.config.Addr)
		if err != nil {
			return fmt.Errorf("failed to create listener: %w", err)
		}
	}

	e.listener = ln

	mux := http.NewServeMux()

	// Wrap /metrics with auth if configured
	if e.authToken != "" {
		metricsHandler := promhttp.Handler()
		mux.Handle("/metrics", authMiddleware(metricsHandler, e.authToken))
	} else {
		mux.Handle("/metrics", promhttp.Handler())
	}

	// Add health check endpoint (no auth required)
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		fmt.Fprintf(w, "OK\n")
	})

	e.server = &http.Server{
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	go func() {
		if err := e.server.Serve(ln); err != nil && err != http.ErrServerClosed {
			log.Error().Err(err).Msg("exporter server error")
		}
	}()

	return nil
}

// Stop stops the HTTP server gracefully
func (e *PowerUsageExporter) Stop() error {
	log.Info().Msg("stopping power usage exporter")

	if e.server == nil {
		return nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := e.server.Shutdown(ctx); err != nil {
		log.Error().Err(err).Msg("error shutting down exporter server")
		return err
	}

	// Clean up port file if it was created
	if e.portFile != "" {
		if err := e.removePortFile(); err != nil {
			log.Warn().Err(err).Msg("failed to remove port file")
		}
	}

	log.Info().Msg("power usage exporter stopped")
	return nil
}

// Addr returns the listening address
func (e *PowerUsageExporter) Addr() string {
	if e.listener != nil {
		return e.listener.Addr().String()
	}
	return e.config.Addr
}

// authMiddleware wraps an http.Handler to require Bearer token authentication
func authMiddleware(next http.Handler, token string) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		expected := "Bearer " + token
		if authHeader != expected {
			w.WriteHeader(http.StatusUnauthorized)
			fmt.Fprintf(w, "Unauthorized\n")
			return
		}
		next.ServeHTTP(w, r)
	})
}

// findAvailablePort searches for an available port in the given range
func (e *PowerUsageExporter) findAvailablePort(start, end int) (int, error) {
	for port := start; port <= end; port++ {
		ln, err := net.Listen("tcp", fmt.Sprintf(":%d", port))
		if err != nil {
			// Port is in use, try next
			continue
		}
		ln.Close() // We just need to verify it's available
		return port, nil
	}
	return 0, fmt.Errorf("no available ports in range %d-%d", start, end)
}

// expandPortFilePath expands ~ to the user's home directory
func expandPortFilePath(path string) string {
	if strings.HasPrefix(path, "~/") {
		home, err := os.UserHomeDir()
		if err != nil {
			return path
		}
		return filepath.Join(home, path[2:])
	}
	return path
}

// writePortFile writes the port number to the port file
func (e *PowerUsageExporter) writePortFile(port int) error {
	log.Info().Str("port-file", e.portFile).Int("port", port).Msg("writing port to file")
	if err := os.WriteFile(e.portFile, []byte(fmt.Sprintf("%d\n", port)), 0600); err != nil {
		return fmt.Errorf("failed to write port file: %w", err)
	}
	return nil
}

// removePortFile removes the port file
func (e *PowerUsageExporter) removePortFile() error {
	log.Info().Str("port-file", e.portFile).Msg("removing port file")
	if err := os.Remove(e.portFile); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to remove port file: %w", err)
	}
	return nil
}

package power_usage_exporter

import (
	"context"
	"net/http"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestNew(t *testing.T) {
	t.Run("creates exporter with default address", func(t *testing.T) {
		exporter := New(&Config{})
		require.NotNil(t, exporter)
		assert.Equal(t, ":8080", exporter.config.Addr)
	})

	t.Run("creates exporter with custom address", func(t *testing.T) {
		exporter := New(&Config{Addr: ":9090"})
		require.NotNil(t, exporter)
		assert.Equal(t, ":9090", exporter.config.Addr)
	})
}

func TestExporterStartStop(t *testing.T) {
	t.Run("starts and stops successfully", func(t *testing.T) {
		exporter := New(&Config{Addr: ":0"}) // Use :0 to get available port
		ctx := context.Background()

		err := exporter.Start(ctx)
		require.NoError(t, err)

		// Give server time to start and bind to port
		time.Sleep(200 * time.Millisecond)

		// Get the actual address (the server assigns a port)
		addr := exporter.Addr()
		require.NotEqual(t, ":0", addr, "server should have bound to a real port")

		// Test health endpoint
		resp, err := http.Get("http://" + addr + "/health")
		require.NoError(t, err)
		assert.Equal(t, http.StatusOK, resp.StatusCode)
		resp.Body.Close()

		// Test metrics endpoint
		resp, err = http.Get("http://" + addr + "/metrics")
		require.NoError(t, err)
		assert.Equal(t, http.StatusOK, resp.StatusCode)
		resp.Body.Close()

		// Stop exporter
		err = exporter.Stop()
		require.NoError(t, err)
	})

	t.Run("handles stop when not started", func(t *testing.T) {
		exporter := New(&Config{})
		err := exporter.Stop()
		require.NoError(t, err)
	})
}

func TestExporterAddr(t *testing.T) {
	exporter := New(&Config{Addr: ":8080"})
	assert.Equal(t, ":8080", exporter.Addr())
}

